def transform(grid):
 out=[row[:] for row in grid]; bg=grid[0][0]; marker=next(v for row in grid for v in row if v!=bg)
 h,w=len(grid),len(grid[0]); pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==marker]
 for i,(r,c) in enumerate(pts):
  for R,C in pts[i+1:]:
   dr,dc=R-r,C-c
   if dr==0 or dc==0 or abs(dr)==abs(dc):
    n=max(abs(dr),abs(dc))
    if n>1:
     sr=0 if dr==0 else (1 if dr>0 else -1); sc=0 if dc==0 else (1 if dc>0 else -1)
     for k in range(1,n): out[r+sr*k][c+sc*k]=3
 return out
